window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b2402c3c21c4c6f2"]={"versions": [{"id": "FIG-b2402c3c21c4c6f2", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs der Funktion <code>E2E_P22Protect()</code> im Kontext des AUTOSAR E2E-Protokolls (Profil 22). Dargestellt wird die Teilspezifikation des Einzelschritts „Increment Counter“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext:</strong> <code>E2E_P22Protect()</code></li>\n<li><strong>Zustandsobjekt/Struktur:</strong> <code>State</code> mit dem Member <code>Counter</code></li>\n<li><strong>Typ-/Wertebereichshinweis (UML-Note):</strong> Expliziter Hinweis auf den Typ <code>uint8</code> mit effektiver Beschränkung auf 16 Werte (Überlauf nach <code>0xF</code> zurück auf <code>0</code>)</li>\n<li><strong>Aktionsknoten:</strong> <code>State-&gt;Counter++</code></li>\n<li><strong>Kontrollflussknoten:</strong> Initialknoten (Start) und Aktivitätsendknoten (Stop)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Initialknoten führt der Kontrollfluss direkt in die Aktion <code>State-&gt;Counter++</code>.</li>\n<li>Die Zählervariable <code>State-&gt;Counter</code> wird inkrementiert.</li>\n<li>Nach Ausführung der Inkrementierung geht der Kontrollfluss direkt in den Aktivitätsendknoten über.</li>\n<li>Eine annotierte Notiz spezifiziert fachlich, dass der Zähler vom Typ <code>uint8</code> ist, jedoch nur 16 Werte durchläuft und nach <code>0xF</code> wieder <code>0</code> folgt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe gemäß <code>[PRS_E2E_00533]</code> für die Senderabsicherung in E2E-Profil 22. Entwickler müssen sicherstellen, dass <code>State-&gt;Counter</code> pro Funktionsaufruf inkrementiert wird und der durch die Notiz definierte 4-Bit-Wertebereich (Modulo 16 bzw. Roll-over nach 15) in der Implementierung eingehalten wird.</p>"}, {"id": "FIG-757326be3b7bc101", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs der Funktion <code>E2E_P22Protect()</code> im Kontext des AUTOSAR E2E-Protokolls (Profil 22). Dargestellt wird die Teilspezifikation des Einzelschritts „Increment Counter“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext:</strong> <code>E2E_P22Protect()</code></li>\n<li><strong>Zustandsobjekt/Struktur:</strong> <code>State</code> mit dem Member <code>Counter</code></li>\n<li><strong>Typ-/Wertebereichshinweis (UML-Note):</strong> Hinweis auf den Datentyp <code>uint8</code> mit 16 genutzten Werten (nach <code>0xF</code> folgt <code>0</code>), assoziiert mit der Inkrementierungsaktion</li>\n<li><strong>Aktionsknoten:</strong></li>\n<li><code>State-&gt;Counter++</code> (Inkrementierung)</li>\n<li><code>State-&gt;Counter %= 16</code> (Modulo-Operation zur Begrenzung auf 4-Bit-Wertebereich)</li>\n<li><strong>Kontrollflussknoten:</strong> Initialknoten und Aktivitätsendknoten</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Initialknoten und verzweigt sequenziell in die Aktion <code>State-&gt;Counter++</code>.</li>\n<li>Nach der Inkrementierung folgt unmittelbar die Aktionsstufe <code>State-&gt;Counter %= 16</code>, welche den Zählerstand explizit modulo 16 begrenzt.</li>\n<li>Nach der Modulo-Berechnung wird der Aktivitätsendknoten erreicht.</li>\n<li>Die Notiz an der ersten Aktionsstufe dokumentiert ergänzend den Typ <code>uint8</code> und den Wertezyklus von 0 bis <code>0xF</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensdefinition nach <code>[PRS_E2E_00533]</code>. Die Begrenzung des Zählers auf den Wertebereich 0 bis 15 (<code>0x0</code> bis <code>0xF</code>) ist nun direkt als eigenständige normative Rechenoperation (<code>State-&gt;Counter %= 16</code>) im Kontrollfluss verankert und zwingend softwareseitig auszuführen.</p>"}, {"id": "FIG-bb4ac826a95f2595", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs der Funktion <code>E2E_P22Protect()</code> im Kontext des AUTOSAR E2E-Protokolls (Profil 22). Dargestellt wird die Teilspezifikation des Einzelschritts „Increment Counter“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext:</strong> <code>E2E_P22Protect()</code></li>\n<li><strong>Zustandsobjekt/Struktur:</strong> <code>State</code> mit dem Member <code>Counter</code></li>\n<li><strong>Typ-/Wertebereichshinweis (UML-Note):</strong> Hinweis auf den Datentyp <code>uint8</code> mit 16 genutzten Werten (nach <code>0xF</code> folgt <code>0</code>), assoziiert mit der Inkrementierungsaktion</li>\n<li><strong>Aktionsknoten:</strong></li>\n<li><code>State-&gt;Counter++</code> (Inkrementierung)</li>\n<li><code>State-&gt;Counter %= 16</code> (Modulo-Operation zur Begrenzung auf 4-Bit-Wertebereich)</li>\n<li><strong>Kontrollflussknoten:</strong> Initialknoten und Aktivitätsendknoten</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Initialknoten und verzweigt sequenziell in die Aktion <code>State-&gt;Counter++</code>.</li>\n<li>Nach der Inkrementierung folgt unmittelbar die Aktionsstufe <code>State-&gt;Counter %= 16</code>, welche den Zählerstand explizit modulo 16 begrenzt.</li>\n<li>Nach der Modulo-Berechnung wird der Aktivitätsendknoten erreicht.</li>\n<li>Die Notiz an der ersten Aktionsstufe dokumentiert ergänzend den Typ <code>uint8</code> und den Wertezyklus von 0 bis <code>0xF</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensdefinition nach <code>[PRS_E2E_00533]</code>. Die Begrenzung des Zählers auf den Wertebereich 0 bis 15 (<code>0x0</code> bis <code>0xF</code>) ist nun direkt als eigenständige normative Rechenoperation (<code>State-&gt;Counter %= 16</code>) im Kontrollfluss verankert und zwingend softwareseitig auszuführen.</p>"}, {"id": "FIG-3f26e88603069e0b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs der Funktion <code>E2E_P22Protect()</code> im Kontext des AUTOSAR E2E-Protokolls (Profil 22). Dargestellt wird die Teilspezifikation des Einzelschritts „Increment Counter“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext:</strong> <code>E2E_P22Protect()</code></li>\n<li><strong>Zustandsobjekt/Struktur:</strong> <code>State</code> mit dem Member <code>Counter</code></li>\n<li><strong>Typ-/Wertebereichshinweis (UML-Note):</strong> Hinweis auf den Datentyp <code>uint8</code> mit 16 genutzten Werten (nach <code>0xF</code> folgt <code>0</code>), assoziiert mit der Inkrementierungsaktion</li>\n<li><strong>Aktionsknoten:</strong></li>\n<li><code>State-&gt;Counter++</code> (Inkrementierung)</li>\n<li><code>State-&gt;Counter %= 16</code> (Modulo-Operation zur Begrenzung auf 4-Bit-Wertebereich)</li>\n<li><strong>Kontrollflussknoten:</strong> Initialknoten und Aktivitätsendknoten</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Initialknoten und verzweigt sequenziell in die Aktion <code>State-&gt;Counter++</code>.</li>\n<li>Nach der Inkrementierung folgt unmittelbar die Aktionsstufe <code>State-&gt;Counter %= 16</code>, welche den Zählerstand explizit modulo 16 begrenzt.</li>\n<li>Nach der Modulo-Berechnung wird der Aktivitätsendknoten erreicht.</li>\n<li>Die Notiz an der ersten Aktionsstufe dokumentiert ergänzend den Typ <code>uint8</code> und den Wertezyklus von 0 bis <code>0xF</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensdefinition nach <code>[PRS_E2E_00533]</code>. Die Begrenzung des Zählers auf den Wertebereich 0 bis 15 (<code>0x0</code> bis <code>0xF</code>) ist nun direkt als eigenständige normative Rechenoperation (<code>State-&gt;Counter %= 16</code>) im Kontrollfluss verankert und zwingend softwareseitig auszuführen.</p>"}], "trans": [{"from": "FIG-b2402c3c21c4c6f2", "to": "FIG-757326be3b7bc101", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung der normativen Aktionsstufe <code>State-&gt;Counter %= 16</code> in den Kontrollfluss nach der Inkrementierung <code>State-&gt;Counter++</code> vor Erreichen des Endzustands.</li>\n</ul>"}, {"from": "FIG-757326be3b7bc101", "to": "FIG-bb4ac826a95f2595", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bb4ac826a95f2595", "to": "FIG-3f26e88603069e0b", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
